with valid as (select id, customer_id, device, browser, country, case when browser in ('Edge', 'Firefox') then 'Core' else 'Other' end as browser_group, coalesce(country, 'OTHER') as country_clean from sessions where browser in ('Safari', 'Chrome')), kept_keys as (select browser from valid intersect select browser from sessions where browser = 'Chrome'), verified as (select s.* from valid s inner join kept_keys k on s.browser = k.browser), joined as (select src.*, c.age, c.name from verified src left join customers c on src.customer_id = c.id), joined_sessions as (select a.*, p.email from joined a left join customers p on a.customer_id <=> p.id), filtered as (select id, customer_id, device, browser, country, browser_group, country_clean, age, name, email, case when device = 'desktop' then 1 else 0 end as is_desktop from joined_sessions where browser is not distinct from 'Edge') select s.id, s.customer_id, s.browser, s.country, s.browser_group, s.age, s.name, s.is_desktop, case when country rlike '^(DE|JP)$' then 'PRIORITY' else 'CORE' end as country_zone, (select avg(a2.balance) from accounts a2 where a2.customer_id = s.customer_id) as avg_account_balance from filtered s order by is_desktop asc nulls first
